export function getAllUbigeoLocations(): UbigeoLocation[] {
  return Object.values(UBIGEO_MAP).sort((a, b) => a.label.localeCompare(b.label));
}

export function getUbigeoByLabel(label: string): UbigeoLocation | undefined {
  return UBIGEO_MAP[label];
}
